full/posix/vscode/ollama-embed/codex-cli.copy:
# Keep generated configuration files out of version control.
echo .chunkhound.json >> .gitignore
# Configure ChunkHound with Ollama embeddings and Codex CLI for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
cat > .chunkhound.json <<'CHUNKHOUND_EOF'
{
  "embedding": {
    "provider": "openai",
    "model": "qwen3-embedding",
    "base_url": "http://localhost:11434/v1"
  },
  "llm": {
    "provider": "codex-cli"
  }
}
CHUNKHOUND_EOF

# Configure VS Code to connect to ChunkHound via MCP.
if [ -f .vscode/mcp.json ]; then
cat <<'CHUNKHOUND_EOF'
.vscode/mcp.json already exists — merge this block into it manually:
{
  "servers": {
    "ChunkHound": {
      "type": "stdio",
      "command": "chunkhound",
      "args": [
        "mcp"
      ]
    }
  }
}
CHUNKHOUND_EOF
else
mkdir -p .vscode
cat > .vscode/mcp.json <<'CHUNKHOUND_EOF'
{
  "servers": {
    "ChunkHound": {
      "type": "stdio",
      "command": "chunkhound",
      "args": [
        "mcp"
      ]
    }
  }
}
CHUNKHOUND_EOF
fi

